const ZONES=DATA.meta.zones;
const STORAGE='aion2-progress-ru-v1';
const COLORS={Cogni:'#b7a8ef',Fera:'#7bd4af',Natura:'#b5d66f',Varian:'#ec9d83',Special:'#e2c27f'};
const $=s=>document.querySelector(s);
const petById=new Map(DATA.pets.map((p,i)=>[String(p.id),{...p,index:i}]));
const monsterByIndex=DATA.monsters;
const zoneSpawnIndexes=ZONES.map(()=>[]);
const spawnsByPetZone=DATA.pets.map(()=>ZONES.map(()=>[]));
DATA.spawns.forEach((s,idx)=>{zoneSpawnIndexes[s[0]].push(idx);spawnsByPetZone[s[1]][s[0]].push(idx);});

const GUIDE=[
  {id:'phase1',label:'Phase 1',title:'Leveling',range:'Start → Level 45',intro:'Move through the story quickly while collecting the permanent power systems you pass along the way. Most normal gear before 45 is temporary, so do not drain enhancement materials into it.',optimal:'Keep the yellow Main Story Quest moving. Side dungeons, Feathers/Monolith levels, Daeva Board points, and your permanent Amulet/Belt are the efficient detours.',items:[
    {id:'p1-0',step:'Step 0',title:'Leave the beginner village',text:['Follow the Main Story Quest (MSQ) until the game sends you out of the starting village. At this point you are simply unlocking the real world and core systems.'],bullets:['Do the yellow story quests.','Equip obvious upgrades; do not worry about optimizing gear yet.']},
    {id:'p1-1',step:'Step 1',title:'MSQ to Level 22',text:['Follow the yellow MSQ to about Level 22. Run side dungeons that are convenient along your route and collect nearby Feathers; Feathers raise your Monolith, a permanent source of stats and gear score.','Equip the highest item-level gear you naturally find. Early gear is replaced quickly, so save enhancement materials.'],bullets:['MSQ first.','Convenient side dungeons and Feathers are worth the detour.','Do not enhance normal temporary gear.']},
    {id:'p1-2',step:'Step 2',title:'Build your permanent Amulet and Belt',text:['Around Level 22, start enhancing only your Amulet and Belt. These two slots stay with the character permanently: Amulet is your efficient damage investment and Belt is your efficient survivability investment.','When either reaches +10, Substance Morph it into blue quality and continue from the new item. By roughly Level 22, aim to have a blue Amulet. If the story feels rough, catch up on side dungeons and Daeva Board progression instead of upgrading throwaway armor.'],bullets:['Priority: Amulet for damage.','Belt if survivability is the problem.','At +10, Substance Morph into blue quality.']},
    {id:'p1-3',step:'Step 3',title:'Krao Cave: solo the Expedition',text:['When the story reaches Krao Cave, create a PRIVATE Expedition room and enter alone. This gives you the progression clear without relying on a group.','For maximum long-term value, leave the final reward box unopened. If you want immediate gear instead, kill both minibosses and open the box at the end.'],note:'Min-max: save the box. Comfort option: kill both minibosses and take the gear.'},
    {id:'p1-4',step:'Step 4',title:'MSQ to about Level 36',text:['Keep pushing MSQ, but now give side dungeons more attention. By about Level 36, aim for Level 20 Monolith from Feathers and roughly half of the side dungeons completed.','When the story sends you into the next Expedition dungeon, make a private room and solo it again. You can usually leave its boxes unopened because side-dungeon and permanent-system progress should carry your damage. If damage still feels low, Regional Quests can fill jewelry slots and add permanent progression.'],bullets:['Target: Level 20 Monolith by ~36.','Target: about half of side dungeons cleared.','Enhance new Clash Runes to +1 only; stop there.']},
    {id:'p1-5',step:'Step 5',title:'Reach Level 45',text:['Finish the MSQ push to Level 45 while continuing convenient side dungeons. Near the Garden, a healthy target is a yellow-quality Amulet, about 75% of side dungeons finished, and a blue Belt at +5 or better.','You still do not need to enhance normal gear. At the end, solo your Draupnir Expedition, kill both minibosses, then roll/open the reward box.'],bullets:['Yellow Amulet.','Blue Belt +5 or better.','~75% side dungeons complete.','Solo Draupnir and take the reward.']}
  ]},
  {id:'phase2',label:'Phase 2',title:'Homework',range:'Level 45 foundation',intro:'Before chasing gear score, clean up the permanent power you skipped while leveling. These jobs make every later gear breakpoint cheaper and easier.',optimal:'Do these alongside early gear farming if you need variety, but try to finish them before spending heavily to force gear score.',items:[
    {id:'p2-sealed',title:'Finish every Sealed Dungeon and Stronghold',text:['Clear every normal-world Sealed Dungeon and Stronghold. These side activities provide permanent account/character progression, enhancement resources, and a large amount of the power expected at 45.'],bullets:['Treat “all of them” as the goal, not just enough to unlock the next activity.']},
    {id:'p2-feathers',title:'Collect all Abyss PvP Feathers',text:['Fly through the Abyss and collect the Feathers even if you have no interest in PvP. They still increase your Monolith/gear score and can help you qualify for higher-bracket content earlier.'],bullets:['This is PvP-zone exploration, not a requirement to actively PvP.']},
    {id:'p2-regionals',title:'Finish Regional Quests',text:['Clean up the regional side-quest sets. They reward additional skill points and Daeva Board points, which are permanent power and should be finished before you try to solve everything with gear.']}
  ]},
  {id:'phase3',label:'Phase 3',title:'Ongoing Progress',range:'Do whenever available',intro:'These are valuable but time-gated or access-gated. Start them early and keep chipping away rather than waiting to finish them in one session.',optimal:'Prioritize Rift access when it appears, spend Nightmare currency on permanent Daeva Board Tokens first, and use enemy-faction trips efficiently.',items:[
    {id:'p3-rifts',title:'Rift Sealed Dungeons and Strongholds',text:['About once every three hours, a Rift can open to the enemy faction homeland. Use it to work on the additional 70 Sealed Dungeons and 10 Strongholds there.','They are lower priority than your home-side homework, but the enhancement stones and uncapped Abyss Points make them extremely valuable over time.'],note:'When a Rift is open, combine several objectives in one trip rather than entering for a single dungeon.'},
    {id:'p3-nightmare',title:'Nightmare progression and Daeva Board Tokens',text:['Keep advancing Nightmare using the Daily/Weekly checklist strategy. Spend Nightmare currency on Daeva Board Tokens first until you have purchased all 50 available from the shop.'],bullets:['Permanent board power comes before optional shop spending.']},
    {id:'p3-spy',title:'Complete all 6 Spy Regional Quests',text:['These are Regional Quests in the enemy faction homeland and require Rift access. There are six; finish all of them for the same kind of permanent progression value as your home Regional Quests.']}
  ]},
  {id:'phase4',label:'Phase 4',title:'Push to 1000 GS',range:'First gear-score breakpoint',intro:'The first gear-score push is mostly about cheap item-level efficiency. You are not building final gear yet; you are squeezing reliable GS from permanent slots, +5 upgrades, and Manastone item level.',optimal:'Use low-cost upgrades across many slots. Do not chase perfect stats: at this stage a green Manastone line is valuable because it gives +2 item level.',items:[
    {id:'p4-amulet',title:'+0 Yellow Amulet',text:['Have your permanent Amulet morphed to yellow quality. It does not need heavy enhancement yet; the quality itself is the important baseline.']},
    {id:'p4-belt',title:'+5 Blue Belt or better',text:['Bring the permanent Belt to at least blue quality and +5. More is fine if you need the survivability or are just short of a breakpoint.']},
    {id:'p4-bracelet',title:'+10 bracelet setup',text:['Bring your bracelet setup to +10, using the Pilgrim/yellow bracelet progression available to you. This is a strong early item-level source.']},
    {id:'p4-pity',title:'Redeem the Draupnir pity box',text:['Use the guaranteed Draupnir pity choice on a slot that gives you a meaningful item-level upgrade rather than duplicating a good slot.']},
    {id:'p4-enhance',title:'+5 every useful item-level 40+ slot',text:['Any item-level 40+ piece you are actually wearing can be efficiently brought to +5. Rift Sealed Dungeons are one of the easiest ways to keep enhancement stones flowing.']},
    {id:'p4-manastone',title:'Put a green Manastone line on every slot',text:['Use only Lesser Manastones for this first pass. You are not hunting perfect stats yet: roll until you get a single green stat line, because green adds +2 item level and cheaply pushes GS.'],note:'Ignore the exact stat for now. Green = item level, and item level is the goal.'}
  ]},
  {id:'phase5',label:'Phase 5',title:'1000 → 1400 GS',range:'Jewelry + homework',intro:'At 1000 GS, start replacing weak jewelry while finishing the permanent homework that should carry you toward 1400.',optimal:'Farm Krao Cave Conquest for jewelry. Skip Draupnir Conquest unless survivability is genuinely a problem.',items:[
    {id:'p5-krao',title:'Farm Krao Cave Conquest jewelry',text:['Run Krao Cave Conquest and target jewelry slots. Aim to equip two or three useful drops, then bring those pieces to +5 and give them Manastones.']},
    {id:'p5-theostone',title:'Equip your weapon Theostone',text:['Put whatever usable Theostone you have into your weapon. At this stage, getting the system active matters more than having the perfect roll.']},
    {id:'p5-homework',title:'Finish Phase 2 homework',text:['Complete the remaining Sealed Dungeons, Strongholds, Abyss Feathers, and Regional Quests. Their permanent gains should move you close to 1400 without forcing expensive gear upgrades.']},
    {id:'p5-cross',title:'Cross 1400 efficiently',text:['If you are only a little short, push a couple of good slots from +5 to +6 or add a little more enhancement to your Amulet/Belt. Spend only enough to cross the bracket.'],note:'Do not broadly over-enhance temporary gear just to overshoot 1400.'}
  ]},
  {id:'phase6',label:'Phase 6',title:'1400 → 1600 GS',range:'Vakron gearing',intro:'This is where your main gear starts becoming worth real enhancement investment. Vakron Sky Island supplies the replacements that carry you through the next brackets.',optimal:'Take the guaranteed Expedition pity first, then farm the mode that fits your goal: solo Expedition for convenience or Conquest for the stronger gold return.',items:[
    {id:'p6-pity',title:'Run Vakron Sky Island Expedition and claim pity',text:['Clear Vakron Sky Island Expedition and claim the pity box. Use the guaranteed choice on the slot where the item-level jump is largest.']},
    {id:'p6-farm',title:'Fill main gear slots from Vakron',text:['Continue with solo Expedition if you prefer solo play, or group Conquest if you want the better gold return. Replace your weaker main armor/gear slots as drops arrive.']},
    {id:'p6-upgrade',title:'+10 the Vakron pieces you keep',text:['Bring good replacement pieces all the way to +10 and Manastone them. At this point you can start caring somewhat more about useful Manastone stats, but progression still comes first.'],note:'Min-max: do not enhance a new piece until the upgrade actually helps you cross the next bracket or improves performance. A same-slot drop with better base stats may appear.'}
  ]},
  {id:'phase7',label:'Phase 7',title:'1600 → 1800 GS',range:'Green Arcana',intro:'1600 unlocks Transcendence and Arcana cards, which are one of the cleanest gear-score jumps in this range.',optimal:'Get the guaranteed card item-level first, then finish normal gear upgrades only as needed to reach 1800.',items:[
    {id:'p7-cards',title:'Get all 4 green Arcana cards',text:['Run Transcendence until all four available Arcana slots are filled with green cards. Each green card is worth +40 GS, so filling the set is a large, efficient jump.']},
    {id:'p7-gear',title:'Finish enough gear upgrades to reach 1800',text:['After the four green cards are in place, finish +10 upgrades or missing Vakron slots until you cross 1800.']}
  ]},
  {id:'phase8',label:'Phase 8',title:'1800 → 2000 GS',range:'Blue Arcana + final pre-2k slots',intro:'At 1800, Transcendence Tier 2 upgrades the Arcana path and your remaining normal gear slots become the main gap to 2000.',optimal:'Replace all four green cards with blue first. Use Vakron for main slots and Uruguru Canyon when jewelry damage upgrades are more valuable.',items:[
    {id:'p8-cards',title:'Replace all 4 Arcana with blue cards',text:['Run Transcendence Tier 2 until all four card slots are blue quality. Each blue card is worth +60 GS.']},
    {id:'p8-fill',title:'Finish missing gear from Vakron or Uruguru Canyon',text:['Use Vakron to finish normal gear slots. If you want more offensive jewelry instead of survivability, mix in a few Uruguru Canyon runs.']},
    {id:'p8-plus10',title:'+10 the pieces you are keeping',text:['Bring these upgrades to +10 and keep Manastones filled. Do not spend enhancement resources on Arcana yet; your normal gear still gives the more important progression here.']}
  ]},
  {id:'phase9',label:'Phase 9',title:'2000 → 2100 GS',range:'The hard wall',intro:'There is no shortcut here. The last 100 GS comes from actually finishing the Vakron/Uruguru gear set and cleaning up weak slots.',optimal:'Spend resources only on upgrades that survive into the 2100 transition. This is also the right point to start putting real time into the Pet Atlas grind.',items:[
    {id:'p9-finish',title:'Finish the remaining gear gaps',text:['Continue Vakron and Uruguru Canyon until your weak slots are replaced and enhanced enough to reach 2100. Expect this breakpoint to take longer than the previous ones.']},
    {id:'p9-pets',title:'Start the serious pet grind',text:['Begin pushing pet ranks while finishing the 2100 wall. Pet bonuses are permanent and the grind becomes a better use of downtime once your basic dungeon gearing is mostly solved.']}
  ]},
  {id:'endgame',label:'Endgame',title:'2100 → 2200+ GS',range:'True endgame loop',intro:'At 2100, progression stops being “replace every drop” and becomes resource allocation: breakthrough upgrades, crafted best-in-slot pieces, higher Arcana, and the newest dungeon tiers.',optimal:'Do not sink premium materials into gear you already know crafted gear will replace. Start banking crafting materials and Amplify Stones while targeting the slots with the longest lifespan.',items:[
    {id:'eg-breakthrough',title:'Use breakthrough selectively',text:['Yellow dungeon gear can go beyond +15 through Breakthrough, using Amplify Stones for five additional enhancement stages. You do not need every dungeon piece at +20; use this where it helps you meet a breakpoint while crafted replacements are still being built.']},
    {id:'eg-crafted',title:'Start crafted gear: Necklace → Ring → Weapon',text:['Crafted gear is the long-term target because its base item level can exceed dungeon gear by a large margin. It is also the gear most worth investing good Manastones and Soul Stones into.','Save crafting materials from this point forward. A strong default order is Necklace, then Ring, then Weapon.']},
    {id:'eg-arcana',title:'Keep progressing Arcana',text:['Transcendence Stage 3 unlocks yellow Arcana to replace blue cards. Keep progressing it, but do not let Arcana spending starve the Amplify Stones you need to move key gear from +15 toward +20.']},
    {id:'eg-content',title:'Move into Ferocious Horn and Fire Temple',text:['Ferocious Horn Expedition/Conquest adds new replacement gear, while Fire Temple opens additional weapon and accessory upgrade paths. Use these as the next source of meaningful replacements instead of continuing to over-invest in outdated slots.']}
  ]}
];

const CHECKLIST={
  daily:[
    {id:'daily-duty',title:'Daily Duty',type:'counter',max:5,kicker:'0 / 5 missions',desc:'Complete five Daily Duty missions. Reroll before committing so the day is not spent on weak reward options.',more:[`Daily Duties give you a selection of missions and rewards to pursue. You do not need to accept the first version offered: missions can be rerolled before you commit.`,`The basic goal is to finish all five duties each day. Spending a little time improving the reward selection first is generally better than blindly accepting low-value missions.`],minmax:[`Reroll each mission a few times looking for high-value options such as tickets, keys, or yellow gear. You do not need to chase a perfect roll forever; a few rerolls is usually enough to improve the average value.`,`When comparing displayed rewards, prioritize valuable items further to the left. Those positions have a higher chance of actually being awarded when the mission is completed.`]},
    {id:'dungeons-energy',title:'Dungeons (Odyle Energy)',type:'check',kicker:'+120/day · 840 cap',desc:'Odyle Energy fuels Conquest dungeons. Make sure you are not sitting at the 840 cap and wasting regeneration; spend it as needed on useful content.',more:[`You gain 120 Odyle Energy per day and can hold up to 840. Use it for Conquests that contain gear or progression items you currently need.`,`You do not need to spend exactly 120 every day. The daily check is simply making sure you are not capped, because regeneration received at 840 is wasted.`],minmax:[`Collect the Expedition pity box and avoid dumping large amounts of Energy into a lower dungeon tier when you expect to unlock a significantly stronger tier soon.`,`When practical, bank Energy and spend it at the highest-tier dungeon you can efficiently run, especially when that tier contains the gear you are actively targeting.`]},
    {id:'shugo-festival',title:'Shugo Festival',type:'counter',max:2,kicker:'2 Shugo Keys/day',desc:'Use the two Shugo Keys granted each day. Pick the event you want and play when its hourly window comes up.',more:[`Shugo Festival events rotate on an hourly schedule. Choose the event you want to run and use your daily Keys when that event becomes available.`,`Placement matters because it determines how many reward selections you receive, so completion alone is not always the goal.`],minmax:[`Do not redeem your reward unless you earned four reward picks when you can avoid it.`,`Four picks are achieved only by finishing 1st or 2nd, so hold out for one of those placements rather than cashing out a weaker reward selection.`]},
    {id:'nightmare',title:'Nightmare',type:'counter',max:2,kicker:'2 charges/day',desc:'Nightmare is a boss-rush progression mode with two daily charges. Use them deliberately instead of spreading attempts across random bosses.',more:[`Nightmare progression is boss-specific, so dividing attempts across too many bosses slows meaningful advancement. Use your daily charges to deliberately push the boss that advances your current path.`,`As stronger boss tiers become available, move your focus forward rather than continuing to over-invest in an earlier tier.`],minmax:[`Focus a single boss until you push it to Rank 10.`,`Progress to a green boss as soon as possible, then move to a blue boss as soon as possible. Concentrated progression is more valuable than partially advancing several lower-tier bosses.`]},
    {id:'supply-request-daily',title:'Supply Request',type:'check',kicker:'Daily turn-ins',desc:'Trade requested materials and craftables for Abyss Points and Enhancement Stones. Complete requests only when the exchange is worthwhile.',more:[`Supply Requests convert materials and crafted goods into progression currencies. You do not necessarily need to personally gather or craft every requested item.`,`The Auction House can often satisfy requests efficiently, making the real decision one of cost versus reward rather than whether the material is already in your bags.`],minmax:[`Buy cheap requested items from the Auction House when the exchange is favorable.`,`Ignore overpriced or bad-value requests. Completing every available request is not automatically optimal if the required items cost more than the AP or Enhancement Stones are worth to you.`]}
  ],
  weekly:[
    {id:'ascension-trial',title:'Ascension Trial',type:'counter',max:3,kicker:'3 runs/week',desc:'Three weekly attempts whose value depends on the difficulty bracket you can reach. Do not rush them early if your gear will improve.',more:[`Treat Ascension Trial as a weekly benchmark rather than something you must clear immediately after reset. Your eligible bracket can increase as your character gains gear during the week.`,`Because attempts are limited, using them too early can lock you into a weaker reward bracket than you could have reached later.`],minmax:[`Wait until you reach the highest bracket you realistically expect to reach that week, then use all three attempts there.`,`The important breakpoints are 1000 GS, 1500 GS, and 2000 GS. If you expect to cross one during the week, delay your runs until you do.`]},
    {id:'daily-dungeon',title:'Daily Dungeon',type:'counter',max:14,kicker:'14 runs/week',desc:'Despite the name, this is effectively a weekly pool of fourteen runs. Distribute them across the week whenever your performance is strongest.',more:[`You do not need to force exactly two runs each day. Your character may gain meaningful power during the week, improving clear speed and overall performance.`,`Treat the fourteen clears as a weekly allowance and schedule them around your upgrades rather than the calendar label.`],minmax:[`This activity is performance based, so wait until you feel comfortable with your kill speed for the week.`,`If you expect significant upgrades soon, delaying the majority of your clears can improve the value of those runs.`]},
    {id:'battlefield',title:'Battlefield',type:'counter',max:3,kicker:'3 wins/week',desc:'Gear-equalized PvP. Secure three Battlefield wins during the week; normal character gear is not the primary barrier here.',more:[`Because gear is equalized, Battlefield is mainly about playing the mode successfully rather than waiting for your character to become stronger.`,`Complete matches until you secure the three required weekly wins.`],minmax:[`There is no meaningful progression trick here.`,`Go win three games.`]},
    {id:'odyle-craft',title:'Odyle Craft',type:'counter',max:20,kicker:'20/week + 4/character',desc:'Craft extra Odyle Energy for additional dungeon runs. There are twenty weekly crafts plus four additional crafts per character.',more:[`Odyle crafting converts your crafting opportunity into additional dungeon Energy. If dungeons are an important upgrade source, these crafts directly increase the amount of progression content available to you.`,`Remember that the twenty-count is the main weekly allowance; the extra four-per-character opportunity sits on top of it.`],minmax:[`Treat crafted Energy like naturally regenerated Energy: it is most valuable when spent on the strongest dungeon tier available to you.`,`If you are close to unlocking a better tier, craft the Energy but consider waiting to spend it.`]},
    {id:'subscriber-shop',title:'Subscriber Shop',type:'counter',max:20,kicker:'20 Odyle purchases/week',desc:'Buy the weekly Odyle Energy allowance from Shop → Wind Breeze Merchant → Special.',more:[`The Subscriber Shop contains another source of Odyle Energy beyond daily regeneration. Check the Special tab under the Wind Breeze Merchant and purchase the weekly allowance when you are actively pushing dungeon progression.`,`This is easy to overlook because it lives in the shop rather than alongside dungeon systems.`],minmax:[`There is no special optimization to the purchase itself.`,`The optimization is how you spend the Energy: favor the highest-value dungeon tier available and avoid unnecessary low-tier runs when a progression breakpoint is close.`]},
    {id:'pve-weeklies',title:'PvE Weeklies',type:'counter',max:12,kicker:'12 missions/week',desc:'Pick up twelve PvE weekly missions from the Command Merchant in any main city and complete them alongside your normal PvE routine.',more:[`These missions are acquired from the Command Merchant in a main city. Since you have several to finish, they are easiest to fold into PvE activities you already intend to run.`,`The available missions and rewards can be rerolled before you commit.`],minmax:[`Reroll these in the same spirit as Daily Duties.`,`Use a few rerolls to avoid weak rewards and prioritize options that meaningfully contribute to your current gearing or progression goals.`]},
    {id:'pvp-weeklies',title:'PvP Weeklies',type:'counter',max:20,kicker:'20 missions/week',desc:'Pick up twenty PvP weekly missions from the Command Merchant in the Abyss and complete them during normal PvP activity.',more:[`These missions add another progression track to Abyss and PvP content. Pick them up from the Abyss Command Merchant and work through them while doing the PvP activities you already care about.`,`Like Daily Duties and PvE weeklies, the available missions can be rerolled.`],minmax:[`Reroll enough to avoid poor-value missions.`,`Give especially high priority to any mission offering PvP Daeva Board pieces.`]},
    {id:'supply-request-weekly',title:'Supply Request',type:'check',kicker:'Weekly turn-ins',desc:'Trade requested materials and craftables for Abyss Points and Enhancement Stones. Complete the requests that make economic sense.',more:[`Supply Requests let you convert materials and crafted goods into AP and Enhancement Stones. Auction House purchases can often satisfy the request more efficiently than gathering everything yourself.`,`Evaluate the cost of the requested item against the value of the reward rather than treating every request as mandatory.`],minmax:[`Buy cheap requested items off the Auction House when the exchange is favorable.`,`Ignore overpriced or bad-value requests instead of overpaying just to clear the checklist.`]},
    {id:'pet-farm',title:'Pet Farm',type:'petfarm',kicker:'Shared with Pet Atlas',desc:'Spend some time advancing the permanent pet collection. Tier 1/2/3 completion below is calculated live from the ranks on the Pet Atlas.',more:[`Pet progression is a long-term collection goal rather than something that actually resets each week. This card is a reminder to devote some weekly time to the collection while keeping one shared set of ranks.`,`Use the Pet Atlas for exact field spawns and zone availability. Any rank change on the Atlas immediately updates these Tier 1, Tier 2, and Tier 3 totals.`],minmax:[`Prioritize pets in limited-access areas, especially Altgard and Abyss sources that do not also exist in Verteron.`,`Farm those limited sources while you have access; shared pets can usually be left for Verteron later.`]}
  ],
  events:[
    {id:'artifact-siege',title:'Artifact Siege',type:'counter',max:2,kicker:'Large-scale Abyss PvP · Wed/Sat default',desc:'The major Abyss PvP siege around a contested Artifact. Stay near the Artifact to earn contribution, survive the final push, and be ready for any Corridor unlocked by a win.',more:[`Artifact Siege happens on scheduled windows rather than on demand. During the fight, your credit is tied to contributing while you remain within roughly 100 yards of the Artifact, so fighting too far away can cost progress even if you are active.`,`Bring Kisks and place them intelligently so a death does not send you back to base during the important part of the siege. The event win itself is decided by the last hit on the Artifact, and a successful Artifact can unlock an Abyss Corridor afterward.`],minmax:[`Stay in contribution range and preserve your position for the final seconds. Time your damage so you have a real chance to land the last hit on the Artifact rather than only padding damage earlier in the fight.`,`Always carry Kisks. A nearby respawn protects your contribution and gets you back in position for the last-hit window and any follow-up Corridor.`]},
    {id:'abyss-corridors',title:'Abyss Corridors',type:'open-counter',kicker:'1 per Artifact win',desc:'A high-value Abyss Point run similar to Daily Dungeon. Each Artifact you win can create another Corridor opportunity.',more:[`Abyss Corridors are short, high-priority farming windows centered on Abyss Points. Enter prepared to maximize the amount of content you can clear rather than treating them as casual runs.`,`Because they are tied to Artifact wins, these opportunities are rarer than ordinary repeatable dungeon content and are disproportionately valuable.`],minmax:[`Use blue scrolls and yellow shards and be ready to kill as many mobs as possible.`,`Focus hard on Corridor performance because this is a rare, extra-powerful AP bonus.`]},
    {id:'abyss-bosses',title:'Abyss Bosses',type:'check',kicker:'After sieges + scheduled spawns',desc:'Abyss bosses appear after sieges and at set times. Attend the spawn and be ready to contest the finishing blow.',more:[`These bosses behave like other contested Abyss objectives: being present for the fight matters, but the final moments matter as well.`,`Track both bosses created after sieges and bosses that appear on their own scheduled windows.`],minmax:[`Like Artifacts, show up in position to attempt the last hit.`,`For Season 1, craft the green box for each boss rather than the higher-tier boxes.`]},
    {id:'field-bosses',title:'Field Bosses',type:'check',kicker:'Outside the Abyss',desc:'Field Bosses are lower-value versions of the same general boss opportunity outside the Abyss. Try to attend when practical.',more:[`Treat Field Bosses as supplemental progression rather than something that should displace significantly stronger activities.`,`When a boss is available and you can reach it without sacrificing something more important, show up and collect the extra value.`],minmax:[`There is no major optimization requirement beyond showing up consistently.`,`They are relatively low value, so do not over-invest time or resources at the expense of stronger progression opportunities.`]}
  ],
  lifetime:[]
};

let state={target:1,ranks:{},page:'guide',guide:{},checklist:{daily:{},weekly:{},events:{}},query:'',category:'',availability:'all',selected:null,hoverPet:null,hoverSpawn:null,zone:0};
try{const raw=localStorage.getItem(STORAGE);if(raw)Object.assign(state,normalizeProgress(JSON.parse(raw),DATA,GUIDE,CHECKLIST));}catch{queueMicrotask(()=>toast('Could not read saved progress. The original data remains in this browser; restore a JSON backup.'));}
let view={x:0,y:0,scale:.1};
let dragging=false,dragMoved=false,startDrag=null;
let activeSpawnIndexes=[],visibleScreen=[];
let canvas=$('#pinCanvas'),ctx=canvas.getContext('2d');
let tileGood=0,tileBad=0;

function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function slug(s){return String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');}
function rank(p){return Math.max(0,Math.min(3,+state.ranks[p.id]||0));}
function done(p){return rank(p)>=state.target;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({target:state.target,ranks:state.ranks,guide:state.guide,checklist:state.checklist}));}catch{toast('Could not save progress. Export a JSON backup to keep your changes.');}}
function zoneNames(p){return p.zones.map(i=>ZONES[i].name);}
function monsterNames(p,zi=null){const arr=zi==null?p.sources.flat():p.sources[zi];return arr.map(i=>monsterByIndex[i].name);}
function availabilityMatch(p){
  if(state.availability==='all')return true;
  if(state.availability==='current')return p.zones.includes(state.zone);
  if(state.availability==='priority')return p.noVerteron;
  if(state.availability==='nonfield')return !p.zones.length;
  if(state.availability.startsWith('zone-'))return p.zones.includes(+state.availability.split('-')[1]);
  return true;
}
function matches(p){const q=state.query.trim().toLowerCase();if(state.category&&p.category!==state.category)return false;if(!availabilityMatch(p))return false;if(!q)return true;return (p.name.toLowerCase().includes(q)||(p.nameRu||'').toLowerCase().includes(q))||monsterNames(p).some(n=>n.toLowerCase().includes(q));}
function filteredPets(){return DATA.pets.filter(matches).sort((a,b)=>Number(done(a))-Number(done(b))||Number(b.noVerteron)-Number(a.noVerteron)||a.category.localeCompare(b.category)||a.name.localeCompare(b.name));}
function petClass(p){return `cat-${p.category}${done(p)?' done':''}${p.noVerteron?' prioritypet':''}${state.selected===p.id?' selected':''}${state.hoverPet===p.id?' hot':''}`;}
function catLetter(c){return ({Cogni:'C',Fera:'F',Natura:'N',Varian:'V',Special:'S'})[c]||'?';}
function zoneBadges(p){const zones=p.zones.map(zi=>`<span class="badge ${zi===state.zone?'here':''}">${ZONES[zi].short}</span>`).join('');const other=!p.zones.length?`<span class="badge">${p.special?'SPECIAL':'OTHER'}</span>`:'';return zones+other+(p.noVerteron?'<span class="badge priority">NO V</span>':'');}
function rowMeta(p){const zi=state.zone;if(p.zones.includes(zi)){const names=monsterNames(p,zi);return `${p.spawnCounts[zi].toLocaleString()} ${ZONES[zi].name} spawn${p.spawnCounts[zi]===1?'':'s'} · ${esc(names.slice(0,2).join(', '))}${names.length>2?` +${names.length-2}`:''}`;}if(!p.zones.length)return p.special?'Special pet · no field-map spawn':'No tracked open-world spawn';return `Available: ${esc(zoneNames(p).join(' · '))}`;}

function renderZoneTabs(){const box=$('#zoneTabs');box.innerHTML=ZONES.map((z,i)=>`<button data-zone="${i}" class="${i===state.zone?'on':''}">${esc(z.name)} <small>${z.petCount}</small></button>`).join('');box.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>switchZone(+b.dataset.zone));}
function renderList(){const pets=filteredPets();let html='',insertedDone=false;for(const p of pets){if(done(p)&&!insertedDone){html+='<div class="donebreak">At target</div>';insertedDone=true;}html+=`<div class="pet ${petClass(p)}" data-pet="${p.id}" tabindex="0" role="button" aria-label="${esc(p.name)}, current rank ${rank(p)}"><div class="petcat">${catLetter(p.category)}</div><div><div class="petname">${esc(p.name)}</div><div class="badges">${zoneBadges(p)}</div><div class="petmeta">${rowMeta(p)}</div></div><div class="rank"><button class="minus" data-rank="-1" aria-label="Decrease ${esc(p.name)} rank" ${rank(p)<=0?'disabled':''}>−</button><output>${rank(p)}</output><button class="plus" data-rank="1" aria-label="Increase ${esc(p.name)} rank" ${rank(p)>=3?'disabled':''}>+</button></div></div>`;}
  if(!pets.length)html='<div class="empty">No pets match this filter.</div>';$('#petList').innerHTML=html;$('#listCount').textContent=`${pets.length} shown`;
  $('#petList').querySelectorAll('.pet').forEach(row=>{const id=+row.dataset.pet;row.addEventListener('mouseenter',()=>setHover(id,null));row.addEventListener('mouseleave',()=>setHover(null,null));row.addEventListener('focus',()=>setHover(id,null));row.addEventListener('blur',()=>setHover(null,null));row.addEventListener('click',e=>{if(e.target.closest('.rank'))return;selectPet(id,true);});row.addEventListener('keydown',e=>{if(e.target.closest('.rank'))return;if(e.key==='Enter'||e.key===' '){e.preventDefault();selectPet(id,true);}});});
  $('#petList').querySelectorAll('[data-rank]').forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();const row=btn.closest('.pet'),id=+row.dataset.pet,p=DATA.pets.find(p=>p.id===id),delta=+btn.dataset.rank;adjustRank(p,delta);}));
}
function renderSummary(){const completed=DATA.pets.filter(done).length,missing=DATA.pets.length-completed;const priorityMissing=DATA.pets.filter(p=>p.noVerteron&&!done(p)).length;const zoneMissing=DATA.pets.filter(p=>p.zones.includes(state.zone)&&!done(p)).length;$('#completeStat').textContent=`${completed} / ${DATA.pets.length}`;$('#missingStat').textContent=missing;$('#priorityStat').textContent=priorityMissing;$('#zoneMissingStat').textContent=zoneMissing;$('#pinStat').textContent=activeSpawnIndexes.length.toLocaleString();document.querySelectorAll('#targetSeg button').forEach(b=>b.classList.toggle('on',+b.dataset.target===state.target));}
function renderDetail(){const id=state.hoverPet??state.selected;const p=DATA.pets.find(p=>p.id===id),z=ZONES[state.zone];if(!p){$('#detail').innerHTML=`<div><div class="tag">${esc(z.name)} pet sources</div><h2>Pick a pet from the list or map.</h2><div class="dmeta">Click the selected pet again, click empty map space, or press Esc to deselect. Pets at or above Rank ${state.target} are hidden from every map.</div></div>`;return;}const here=p.zones.includes(state.zone);let desc;if(here){const names=p.sources[state.zone].map(i=>{const m=monsterByIndex[i];return `${m.name} (Lv ${m.level})`;});desc=`${p.spawnCounts[state.zone].toLocaleString()} verified ${z.name} spawns · ${esc(names.join(' · '))}`;}else if(!p.zones.length){desc=p.special?'Special collection pet; no open-world map source is attached.':'No verified source in Verteron, Altgard, or Lower Reshanta.';}else{desc=`No ${z.name} source. Available in ${esc(zoneNames(p).join(', '))}.`;}
  const zoneButtons=!here&&!done(p)?p.zones.map(zi=>`<button data-goto-zone="${zi}">Go to ${esc(ZONES[zi].name)}</button>`).join(''):'';
  const zoneLine=p.zones.length?`Tracked field zones: ${esc(zoneNames(p).join(' · '))}`:'Tracked field zones: none';
  $('#detail').innerHTML=`<div><div class="tag">${esc(p.category)} · Rank ${rank(p)} / 3${done(p)?' · target met':''}${p.noVerteron?' · no Verteron field source':''}</div><h2>${esc(p.name)}</h2><div class="dmeta">${desc}<br>${zoneLine}</div></div><div class="actions">${here&&!done(p)?'<button id="focusPet">Fit pet spawns</button>':''}${zoneButtons}<button id="clearPet">Deselect</button><button id="rankDown" ${rank(p)<=0?'disabled':''}>− Rank</button><button id="rankUp" ${rank(p)>=3?'disabled':''}>+ Rank</button></div>`;
  $('#focusPet')?.addEventListener('click',()=>centerPet(p));$('#rankDown')?.addEventListener('click',()=>adjustRank(p,-1));$('#rankUp')?.addEventListener('click',()=>adjustRank(p,1));$('#clearPet')?.addEventListener('click',clearSelection);document.querySelectorAll('[data-goto-zone]').forEach(b=>b.onclick=()=>switchZone(+b.dataset.gotoZone,true,p));
}

function guideDone(id){return !!state.guide[id];}
function setGuideDone(id,val){state.guide[id]=!!val;save();renderGuide();}
function guideItemHtml(item){const done=guideDone(item.id);return `<article class="guideItem ${done?'done':''}"><button class="guideCheck ${done?'on':''}" data-guide-check="${esc(item.id)}" aria-pressed="${done}" aria-label="${done?'Mark incomplete':'Mark complete'}: ${esc(item.title)}">✓</button><div><div class="guideStep">${esc(item.step||'Checklist')}</div><h4>${esc(item.title)}</h4><div class="guideText">${(item.text||[]).map(t=>`<p>${esc(t)}</p>`).join('')}</div>${item.bullets?.length?`<ul class="guideBullets">${item.bullets.map(b=>`<li>${esc(b)}</li>`).join('')}</ul>`:''}${item.note?`<div class="guideNote">${esc(item.note)}</div>`:''}</div></article>`;}
function guidePhaseHtml(phase){const done=phase.items.filter(i=>guideDone(i.id)).length,total=phase.items.length,pct=total?Math.round(done/total*100):0;return `<section class="guidePhase ${done===total?'guideDoneAll':''}" id="guide-${phase.id}"><div class="guidePhaseHead"><div class="guidePhaseTop"><div><div class="guidePhaseLabel">${esc(phase.label)} · ${esc(phase.range)}</div><h3>${esc(phase.title)}</h3><p>${esc(phase.intro)}</p></div><div class="guidePhaseCount">${done} / ${total} complete</div></div><div class="guideAdvice"><b>Best approach:</b> ${esc(phase.optimal)}</div></div><div class="guideBar"><i style="width:${pct}%"></i></div><div class="guideItems">${phase.items.map(guideItemHtml).join('')}</div></section>`;}
function renderGuide(){const box=$('#guideSections'),jump=$('#guideJump');if(!box||!jump)return;box.innerHTML=GUIDE.map(guidePhaseHtml).join('');jump.innerHTML=GUIDE.map(p=>`<button data-guide-jump="${p.id}">${esc(p.label.replace('Phase ','P'))}</button>`).join('');box.querySelectorAll('[data-guide-check]').forEach(btn=>btn.onclick=()=>setGuideDone(btn.dataset.guideCheck,!guideDone(btn.dataset.guideCheck)));jump.querySelectorAll('[data-guide-jump]').forEach(btn=>btn.onclick=()=>document.getElementById('guide-'+btn.dataset.guideJump)?.scrollIntoView({behavior:'smooth',block:'start'}));}

function checklistSection(section){if(!state.checklist[section])state.checklist[section]={};return state.checklist[section];}
function taskValue(section,task){const v=checklistSection(section)[task.id];if(task.type==='check'||task.type==='petfarm')return !!v;return Math.max(0,+v||0);}
function taskComplete(section,task){const v=taskValue(section,task);if(task.type==='check'||task.type==='petfarm')return !!v;if(task.type==='open-counter')return v>0;return v>=task.max;}
function setTaskValue(section,task,val){const box=checklistSection(section);if(task.type==='check'||task.type==='petfarm')box[task.id]=!!val;else if(task.type==='open-counter')box[task.id]=Math.max(0,Math.floor(+val||0));else box[task.id]=Math.max(0,Math.min(task.max,Math.floor(+val||0)));save();renderProgression();}
function petTierStats(){return [1,2,3].map(t=>DATA.pets.filter(p=>rank(p)>=t).length);}
function paragraphHtml(arr){return arr.map(x=>`<p>${esc(x)}</p>`).join('');}
function taskControlHtml(section,task){const v=taskValue(section,task);if(task.type==='counter')return `<div class="taskCounter"><button data-task-delta="-1" data-section="${section}" data-task="${task.id}" ${v<=0?'disabled':''}>−</button><output>${v} / ${task.max}</output><button data-task-delta="1" data-section="${section}" data-task="${task.id}" ${v>=task.max?'disabled':''}>+</button></div>`;if(task.type==='open-counter')return `<div class="taskCounter"><button data-task-delta="-1" data-section="${section}" data-task="${task.id}" ${v<=0?'disabled':''}>−</button><output>${v} done</output><button data-task-delta="1" data-section="${section}" data-task="${task.id}">+</button></div>`;if(task.type==='petfarm'){const [r1,r2,r3]=petTierStats();return `<div><div class="petFarmStats"><div class="petFarmStat"><span>Tier 1</span><b>${r1} / ${DATA.pets.length}</b></div><div class="petFarmStat"><span>Tier 2</span><b>${r2} / ${DATA.pets.length}</b></div><div class="petFarmStat"><span>Tier 3</span><b>${r3} / ${DATA.pets.length}</b></div></div><div class="petFarmActions"><button data-open-pets>Open Pet Atlas</button><button class="taskCheck ${v?'on':''}" data-task-check data-section="${section}" data-task="${task.id}">${v?'Farmed this week':'Mark farmed this week'}</button></div></div>`;}return `<button class="taskCheck ${v?'on':''}" data-task-check data-section="${section}" data-task="${task.id}">${v?'Done':'Mark done'}</button>`;}
function taskCardHtml(section,task){return `<article class="taskCard ${taskComplete(section,task)?'taskDone':''}"><div class="taskTop"><div class="taskTitle"><div class="taskKicker">${esc(task.kicker||'')}</div><h4>${esc(task.title)}</h4></div><div class="taskControl">${task.type==='petfarm'?'':taskControlHtml(section,task)}</div></div><div class="taskDesc">${esc(task.desc)}</div>${task.type==='petfarm'?taskControlHtml(section,task):''}<div class="taskDetails"><details><summary>More Info</summary><div class="detailText">${paragraphHtml(task.more||[])}</div></details><details class="minmax"><summary>Min-Max</summary><div class="detailText">${paragraphHtml(task.minmax||[])}</div></details></div></article>`;}
function sectionProgressInfo(section,tasks){if(!tasks.length)return {done:0,total:0,pct:0};const done=tasks.filter(t=>taskComplete(section,t)).length;return {done,total:tasks.length,pct:Math.round(done/tasks.length*100)};}
function sectionHtml(section,label,resettable=false){const tasks=CHECKLIST[section],info=sectionProgressInfo(section,tasks),id=section+'Section';if(!tasks.length)return `<section class="checkSection" id="${id}"><div class="sectionHead"><div class="sectionTitle"><h3>${label}</h3><span>Permanent</span></div></div><div class="emptyLifetime">Lifetime tasks have not been added yet. This section is ready for permanent character milestones and will never be affected by Daily or Weekly resets.</div></section>`;return `<section class="checkSection" id="${id}"><div class="sectionHead"><div class="sectionTitle"><h3>${label}</h3><span>${section==='events'?'Scheduled / opportunistic':section}</span></div><div class="sectionTools"><span class="sectionProgress">${info.done} / ${info.total} tasks complete</span>${resettable?`<button class="resetSection" data-reset-section="${section}">Reset ${label}</button>`:''}</div></div><div class="sectionBar"><i style="width:${info.pct}%"></i></div><div class="taskGrid">${tasks.map(t=>taskCardHtml(section,t)).join('')}</div></section>`;}
function renderProgression(){const box=$('#progressionSections');if(!box)return;box.innerHTML=sectionHtml('daily','Daily',true)+sectionHtml('weekly','Weekly',true)+sectionHtml('events','Events',false)+sectionHtml('lifetime','Lifetime',false);box.querySelectorAll('[data-task-delta]').forEach(btn=>btn.onclick=()=>{const section=btn.dataset.section,task=CHECKLIST[section].find(t=>t.id===btn.dataset.task);setTaskValue(section,task,taskValue(section,task)+(+btn.dataset.taskDelta));});box.querySelectorAll('[data-task-check]').forEach(btn=>btn.onclick=()=>{const section=btn.dataset.section,task=CHECKLIST[section].find(t=>t.id===btn.dataset.task);setTaskValue(section,task,!taskValue(section,task));});box.querySelectorAll('[data-reset-section]').forEach(btn=>btn.onclick=()=>openChecklistReset(btn.dataset.resetSection));box.querySelectorAll('[data-open-pets]').forEach(btn=>btn.onclick=()=>switchPage('pets'));}
function switchPage(page){state.page=['guide','progression','pets'].includes(page)?page:'guide';history.replaceState(null,'','#'+state.page);document.querySelectorAll('.languageSwitch a').forEach(a=>{const url=new URL(a.href);url.hash=state.page;a.href=url.href;});const pets=state.page==='pets',progression=state.page==='progression',guide=state.page==='guide';$('#petSummary').classList.toggle('hidePage',!pets);$('#petPage').classList.toggle('hidePage',!pets);$('#progressionPage').classList.toggle('hidePage',!progression);$('#guidePage').classList.toggle('hidePage',!guide);$('#resetBtn').classList.toggle('hide',!pets);$('#appTitle').textContent=guide?'AION 2 Simplified Progression':progression?'AION 2 Progression Checklist':'AION 2 Pet Atlas';document.querySelectorAll('#appNav [data-page]').forEach(b=>b.classList.toggle('on',b.dataset.page===state.page));if(pets)requestAnimationFrame(()=>{resizeCanvas();fitMap();render();});else if(progression)renderProgression();else renderGuide();}
function openChecklistReset(section){const label=section==='daily'?'Daily':'Weekly',d=$('#modal');$('#modalTitle').textContent=`Reset ${label} progress`;$('#modalBody').innerHTML=`<p>This clears all ${label} checklist progress. Permanent Pet Atlas ranks are not affected.</p><div class="modalbuttons"><button id="confirmChecklistReset">Reset ${label}</button></div>`;$('#confirmChecklistReset').onclick=()=>{state.checklist[section]={};save();renderProgression();d.close();toast(`${label} progress reset.`);};d.showModal();}

function render(){renderZoneTabs();renderList();rebuildActiveSpawns();renderSummary();renderDetail();drawPins();renderProgression();renderGuide();}
function setRank(p,val){if(!p)return;state.ranks[p.id]=Math.max(0,Math.min(3,val));save();if(done(p)&&state.hoverPet===p.id)state.hoverPet=null;render();}
function adjustRank(p,delta){if(!p)return;if(p.special){setRank(p,delta>0?3:0);return;}setRank(p,rank(p)+delta);}
function clearSelection(){state.selected=null;state.hoverPet=null;state.hoverSpawn=null;renderList();renderDetail();drawPins();showTooltip(null);}
function selectPet(id,center=false){const p=DATA.pets.find(p=>p.id===id);if(!p)return;if(state.selected===id){clearSelection();return;}state.selected=id;if(center&&p.zones.length&&!p.zones.includes(state.zone)){switchZone(p.zones[0],true,p);return;}renderList();renderDetail();drawPins();if(center&&p.zones.length&&!done(p))centerPet(p);}
function setHover(id,spawnIdx){if(state.hoverPet===id&&state.hoverSpawn===spawnIdx)return;state.hoverPet=id;state.hoverSpawn=spawnIdx;document.querySelectorAll('.pet').forEach(r=>r.classList.toggle('hot',id!=null&&+r.dataset.pet===id));renderDetail();drawPins();}
function rebuildActiveSpawns(){activeSpawnIndexes=[];for(const i of zoneSpawnIndexes[state.zone]){const s=DATA.spawns[i],p=DATA.pets[s[1]];if(!done(p)&&matches(p))activeSpawnIndexes.push(i);}$('#pinStat').textContent=activeSpawnIndexes.length.toLocaleString();}

function resizeCanvas(){const r=$('#map').getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));canvas.style.width=r.width+'px';canvas.style.height=r.height+'px';ctx.setTransform(dpr,0,0,dpr,0,0);drawPins();}
function applyView(){const st=$('#stage');st.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;drawPins();}
function fitMap(){const z=ZONES[state.zone],r=$('#map').getBoundingClientRect();view.scale=Math.min(r.width/z.mapSize,r.height/z.mapSize)*.96;view.x=(r.width-z.mapSize*view.scale)/2;view.y=(r.height-z.mapSize*view.scale)/2;applyView();}
function zoomAt(f,sx,sy){const old=view.scale,next=Math.max(.025,Math.min(3,old*f));const ratio=next/old;view.x=sx-(sx-view.x)*ratio;view.y=sy-(sy-view.y)*ratio;view.scale=next;applyView();}
function centerPet(p){const idxs=spawnsByPetZone[DATA.pets.indexOf(p)][state.zone];if(!idxs.length)return;let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const i of idxs){const s=DATA.spawns[i];minX=Math.min(minX,s[2]);maxX=Math.max(maxX,s[2]);minY=Math.min(minY,s[3]);maxY=Math.max(maxY,s[3]);}const r=$('#map').getBoundingClientRect(),pad=150,w=Math.max(120,maxX-minX),h=Math.max(120,maxY-minY);view.scale=Math.min(1.5,Math.max(.05,Math.min((r.width-pad)/w,(r.height-pad)/h)));view.x=r.width/2-(minX+maxX)/2*view.scale;view.y=r.height/2-(minY+maxY)/2*view.scale;applyView();}
function drawPetMarker(x,y,color,r,hot=false){ctx.save();ctx.translate(x,y);if(hot){ctx.beginPath();ctx.arc(0,0,r+4,0,Math.PI*2);ctx.fillStyle='#fff4b833';ctx.fill();ctx.lineWidth=2;ctx.strokeStyle='#fff0a8';ctx.stroke();}ctx.beginPath();ctx.arc(0,1,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();ctx.lineWidth=1.2;ctx.strokeStyle='#08120f';ctx.stroke();if(r>=5){ctx.fillStyle='#102019';ctx.beginPath();ctx.ellipse(0,1,r*.42,r*.34,0,0,Math.PI*2);ctx.fill();for(const [dx,dy] of [[-r*.45,-r*.45],[0,-r*.62],[r*.45,-r*.45]]){ctx.beginPath();ctx.arc(dx,dy,Math.max(1,r*.19),0,Math.PI*2);ctx.fill();}}ctx.restore();}
function drawPins(){if(!ctx)return;const r=$('#map').getBoundingClientRect();ctx.clearRect(0,0,r.width,r.height);visibleScreen=[];const hover=state.hoverPet??state.selected;const baseR=view.scale<.08?2.0:view.scale<.16?2.6:view.scale<.35?3.4:4.2;for(const idx of activeSpawnIndexes){const s=DATA.spawns[idx],p=DATA.pets[s[1]];const sx=view.x+s[2]*view.scale,sy=view.y+s[3]*view.scale;if(sx<-16||sy<-16||sx>r.width+16||sy>r.height+16)continue;const hot=hover!=null&&p.id===hover;ctx.globalAlpha=hover!=null&&!hot?.25:1;drawPetMarker(sx,sy,COLORS[p.category],hot?Math.max(6,baseR+2):baseR,hot);visibleScreen.push([idx,sx,sy,hot?11:Math.max(7,baseR+4)]);}ctx.globalAlpha=1;const activePets=new Set(activeSpawnIndexes.map(i=>DATA.spawns[i][1])).size;$('#mapStatus').textContent=`${activeSpawnIndexes.length.toLocaleString()} pins · ${activePets} missing pets`;}
function markerAt(x,y){let best=null,bestD=Infinity;for(const v of visibleScreen){const dx=v[1]-x,dy=v[2]-y,d=dx*dx+dy*dy,rr=v[3]*v[3];if(d<=rr&&d<bestD){best=v;bestD=d;}}return best?best[0]:null;}
function showTooltip(idx,x,y){const el=$('#tooltip');if(idx==null){el.style.display='none';return;}const s=DATA.spawns[idx],p=DATA.pets[s[1]],m=monsterByIndex[s[4]],z=ZONES[s[0]];const wx=(s[2]-z.center)/z.worldScale,wz=(s[3]-z.center)/z.worldScale;el.innerHTML=`<b>${esc(p.name)}</b><div class="tmeta">${esc(p.category)} · Rank ${rank(p)} / target ${state.target}<br>${esc(m.name)} · Lv ${m.level} · ${esc(z.name)}<br>World X ${wx.toFixed(1)} · Z ${wz.toFixed(1)}</div>`;const mr=$('#map').getBoundingClientRect(),tw=270,th=96;el.style.left=Math.min(mr.width-tw-8,Math.max(8,x+14))+'px';el.style.top=Math.min(mr.height-th-8,Math.max(8,y+14))+'px';el.style.display='block';}

function configureStage(){const z=ZONES[state.zone],st=$('#stage');st.style.width=z.mapSize+'px';st.style.height=z.mapSize+'px';}
function loadTiles(){const z=ZONES[state.zone],code=z.mapCode,host=`https://aion2-interactive-map.github.io/aion2-interactive-map/UI/Map/WorldMap/${code}/Res/`,fallback=`https://raw.githubusercontent.com/aion2-interactive-map/aion2-interactive-map/master/public/UI/Map/WorldMap/${code}/Res/`,box=$('#tiles');box.innerHTML='';tileGood=0;tileBad=0;$('#mapNotice').style.display='none';for(let y=0;y<z.tilesY;y++)for(let x=0;x<z.tilesX;x++){const name=`${code}_${String(x).padStart(2,'0')}_${String(y).padStart(2,'0')}.webp`;const img=document.createElement('img');img.className='tile';img.alt='';img.draggable=false;img.decoding='async';img.style.left=(x*z.tileSize)+'px';img.style.top=(y*z.tileSize)+'px';img.style.width=z.tileSize+'px';img.style.height=z.tileSize+'px';let tried=false;img.onload=()=>{tileGood++;if(tileGood>0)$('#mapNotice').style.display='none';};img.onerror=()=>{if(!tried){tried=true;img.src=fallback+name;}else{tileBad++;if(tileBad>=z.tilesX*z.tilesY&&tileGood===0)$('#mapNotice').style.display='block';img.style.display='none';}};img.src=host+name;box.append(img);}}
function switchZone(zi,center=false,p=null){if(zi===state.zone){if(center&&p)centerPet(p);return;}state.zone=zi;state.hoverPet=null;state.hoverSpawn=null;configureStage();loadTiles();render();requestAnimationFrame(()=>{fitMap();if(center&&p&&!done(p))centerPet(p);});}

function exportProgress(){const payload={schema:'aion2-companion-v5',exportedAt:new Date().toISOString(),target:state.target,ranks:state.ranks,guide:state.guide,checklist:state.checklist};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='aion2-companion-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Progress exported.');}
function importProgress(obj){const next=normalizeProgress(obj,DATA,GUIDE,CHECKLIST);Object.assign(state,next);save();render();toast('Progress imported.');}
function toast(msg){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),2200);}
function openImport(){const d=$('#modal');$('#modalTitle').textContent='Import progress';$('#modalBody').innerHTML='<p>Choose a previously exported progress JSON. Pet ranks will be replaced; checklist progress is imported when present.</p><div class="modalbuttons"><button id="chooseFile">Choose JSON file</button></div>';$('#chooseFile').onclick=()=>$('#fileInput').click();d.showModal();}
function openReset(){const d=$('#modal');$('#modalTitle').textContent='Reset progress';$('#modalBody').innerHTML=`<p>This resets all ${DATA.pets.length} tracked pets to Rank 0 in this browser.</p><div class="modalbuttons"><button id="confirmReset">Reset all ranks</button></div>`;$('#confirmReset').onclick=()=>{state.ranks={};save();render();d.close();toast('Ranks reset.');};d.showModal();}


document.querySelectorAll('#appNav [data-page]').forEach(b=>b.addEventListener('click',()=>switchPage(b.dataset.page)));
document.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.jump)?.scrollIntoView({behavior:'smooth',block:'start'})));

$('#search').addEventListener('input',e=>{state.query=e.target.value;render();});$('#category').addEventListener('change',e=>{state.category=e.target.value;render();});$('#availability').addEventListener('change',e=>{state.availability=e.target.value;render();});document.querySelectorAll('#targetSeg button').forEach(b=>b.addEventListener('click',()=>{state.target=+b.dataset.target;save();render();}));$('#exportBtn').onclick=exportProgress;$('#importBtn').onclick=openImport;$('#resetBtn').onclick=openReset;$('#modalClose').onclick=()=>$('#modal').close();$('#fileInput').addEventListener('change',async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>1024*1024)throw Error('File exceeds 1 MB. Choose a progress export.');importProgress(JSON.parse(await f.text()));$('#modal').close();}catch(err){toast(err.message||'Import failed.');}finally{e.target.value='';}});
$('#zoomIn').onclick=()=>{const r=$('#map').getBoundingClientRect();zoomAt(1.35,r.width/2,r.height/2)};$('#zoomOut').onclick=()=>{const r=$('#map').getBoundingClientRect();zoomAt(1/1.35,r.width/2,r.height/2)};$('#fit').onclick=fitMap;
const map=$('#map');
map.addEventListener('wheel',e=>{if(e.target.closest('.maptools'))return;e.preventDefault();const r=map.getBoundingClientRect();zoomAt(e.deltaY<0?1.16:1/1.16,e.clientX-r.left,e.clientY-r.top)},{passive:false});
function stopDrag(e,cancelled=false){if(!dragging)return;dragging=false;map.classList.remove('drag');startDrag=null;try{if(e?.pointerId!=null&&map.hasPointerCapture?.(e.pointerId))map.releasePointerCapture(e.pointerId)}catch{}showTooltip(null);if(cancelled){setHover(null,null);map.style.cursor='grab';}}
map.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('.maptools'))return;e.preventDefault();dragging=true;dragMoved=false;startDrag={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};try{map.setPointerCapture(e.pointerId)}catch{}map.classList.add('drag');setHover(null,null);showTooltip(null);});
map.addEventListener('pointermove',e=>{const r=map.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(dragging){e.preventDefault();if(!startDrag)return;const dx=e.clientX-startDrag.x,dy=e.clientY-startDrag.y;if(Math.abs(dx)+Math.abs(dy)>3)dragMoved=true;view.x=startDrag.vx+dx;view.y=startDrag.vy+dy;if(Number.isFinite(view.x)&&Number.isFinite(view.y))applyView();return;}if(x<0||y<0||x>r.width||y>r.height){setHover(null,null);showTooltip(null);map.style.cursor='grab';return;}const idx=markerAt(x,y);if(idx!=null){const p=DATA.pets[DATA.spawns[idx][1]];setHover(p.id,idx);showTooltip(idx,x,y);map.style.cursor='pointer';}else{setHover(null,null);showTooltip(null);map.style.cursor='grab';}});
map.addEventListener('pointerup',e=>{if(!dragging)return;const moved=dragMoved;stopDrag(e,false);if(moved)return;const r=map.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(x<0||y<0||x>r.width||y>r.height){clearSelection();return;}const idx=markerAt(x,y);if(idx!=null){const p=DATA.pets[DATA.spawns[idx][1]];selectPet(p.id,false);const row=document.querySelector(`[data-pet="${p.id}"]`);row?.scrollIntoView({block:'nearest',behavior:'smooth'});}else{clearSelection();}});
map.addEventListener('pointercancel',e=>stopDrag(e,true));
map.addEventListener('lostpointercapture',e=>{if(dragging)stopDrag(e,true)});
map.addEventListener('pointerleave',()=>{if(!dragging){setHover(null,null);showTooltip(null);map.style.cursor='grab';}});
window.addEventListener('blur',()=>stopDrag(null,true));
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#modal').open){clearSelection();}});
window.addEventListener('resize',()=>{resizeCanvas();fitMap();});
$('#footerCounts').textContent=`${DATA.pets.length} Global pets · ${DATA.meta.spawnCount.toLocaleString()} verified field-source spawns · ${DATA.meta.priorityCount} field pets with no Verteron source.`;
configureStage();loadTiles();render();switchPage(location.hash.slice(1));requestAnimationFrame(()=>{resizeCanvas();fitMap();});
